('방문을 열면 그곳엔 괴물','긴편지',array['액션']::text[],'모경은 의문의 누군가에게 택배를 받는다.','naver','https://comic.naver.com/webtoon/list?titleId=845387','https://shared-comic.pstatic.net/thumb/webtoon/845387/thumbnail/thumbnail_IMAG21_e261810e-f8ad-44d8-890c-7318fc74499e.jpg'),
('첫날밤만 세 번째','나라나라',array['로맨스']::text[],'스스로의 인생에 허망함과 회의감을 느끼던 29세 ‘백도희’.','naver','https://comic.naver.com/webtoon/list?titleId=804157','https://shared-comic.pstatic.net/thumb/webtoon/804157/thumbnail/thumbnail_IMAG21_9bf245bf-319b-4902-8ebd-438ca75c6e04.jpg')
),
ins as (
  insert into public.works (title_ko, author, genres, blurb_ko, cover_url, status, is_curated, sort)
  select i.title, i.author, i.genres, i.blurb, nullif(i.cover,''), '완결', false,
         2500 + row_number() over (order by i.title)
    from imp i
   where not exists (select 1 from public.works w where w.title_ko = i.title)
  returning id, title_ko
)
insert into public.work_legal_links (work_id, platform_key, url, sort)
select ins.id, imp.pk, imp.url, 0
  from imp join ins on ins.title_ko = imp.title;


